// ENG-2244 live verification: "Create new" relation type dialog on the canvas relation menu.
import fs from "node:fs";

const TS = Date.now();
const MARK = "eng2244t";
const NODE = { question: "WwAi4HfE0", hypothesis: "KjGdEVccK", conclusion: "dbGZu8Esl", consequence: "8ltsMmQEq", result: "nCZJL7eK5", test: "bykXiDWGM" };
const L0 = `${MARK} relates`;
const C0 = `${MARK} related by`;
const C1 = `${MARK} T1 supported by`;
const C2 = `${MARK} T2 supported by`;

const sleep = (page, ms) => page.waitForTimeout(ms);

const installEditorFinder = (page) =>
  page.evaluate(() => {
    const isEd = (v) => v && typeof v === "object" && typeof v.getCurrentPageShapes === "function" && v.store;
    window.__e2244Ed = () => {
      const c = document.querySelector(".roamjs-tldraw-canvas-container");
      const el = c?.querySelector(".tl-canvas") || c?.querySelector(".tl-container");
      if (!el) return null;
      const key = Object.keys(el).find((k) => k.startsWith("__reactFiber$"));
      let f = key ? el[key] : null;
      for (let i = 0; f && i < 400; i += 1, f = f.return) {
        const p = f.memoizedProps;
        if (isEd(p?.editor)) return p.editor;
        if (isEd(p?.value)) return p.value;
      }
      return null;
    };
    return true;
  });

const closeDialogs = async (page) => {
  for (let i = 0; i < 4; i += 1) {
    if (!(await page.evaluate(() => Boolean(document.querySelector(".bp3-dialog, .rm-settings"))))) return;
    await page.keyboard.press("Escape");
    await sleep(page, 400);
  }
};

const mouseDrag = async (page, from, to, steps = 15) => {
  await page.mouse.move(from.x, from.y);
  await page.mouse.down();
  for (let i = 1; i <= steps; i += 1) {
    await page.mouse.move(from.x + ((to.x - from.x) * i) / steps, from.y + ((to.y - from.y) * i) / steps);
    await sleep(page, 25);
  }
  await page.mouse.up();
};

const shapeCenter = (page, id) =>
  page.evaluate((id) => {
    const ed = window.__e2244Ed();
    const b = ed.getShapePageBounds(id);
    const p = ed.pageToScreen({ x: b.midX, y: b.midY });
    return { x: p.x, y: p.y };
  }, id);

const dropdown = (page) => page.locator(".roamjs-tldraw-canvas-container div.shadow-lg").filter({ hasText: "Relation Type" }).first();
const dropdownButtons = async (page) => (await dropdown(page).locator("button").allInnerTexts()).map((t) => t.replace(/\s+/g, " ").trim());
const dropdownVisible = async (page) => (await dropdown(page).count()) > 0 && (await dropdown(page).isVisible());
const dropdownText = async (page) => ((await dropdown(page).count()) ? (await dropdown(page).innerText()).replace(/\s+/g, " ").trim() : null);

const shot = async (page, outDir, name) => {
  const box = await page.locator(".roamjs-tldraw-canvas-container").first().boundingBox();
  const path = `${outDir}/${name}`;
  await page.screenshot({ path, clip: box || undefined });
  return path;
};

const dragHandle = async (page, fromId, toId) => {
  await page.evaluate(() => { window.__e2244Ed().selectNone(); return true; });
  const c = await shapeCenter(page, fromId);
  await page.mouse.click(c.x, c.y);
  await sleep(page, 600);
  const handles = page.locator(".roamjs-tldraw-canvas-container .cursor-crosshair");
  const n = await handles.count();
  if (!n) throw new Error("no drag handles after selecting node");
  const t = await shapeCenter(page, toId);
  let best = null; let bestD = Infinity;
  for (let i = 0; i < n; i += 1) {
    const b = await handles.nth(i).boundingBox();
    const d = b ? Math.hypot(b.x - t.x, b.y - t.y) : Infinity;
    if (d < bestD) { best = b; bestD = d; }
  }
  await mouseDrag(page, { x: best.x + best.width / 2, y: best.y + best.height / 2 }, t);
  await sleep(page, 800);
  if (!(await dropdownVisible(page))) {
    const toast = await page.locator(".tlui-toast__container").allInnerTexts().catch(() => []);
    throw new Error(`relation menu did not open; toasts: ${JSON.stringify(toast)}`);
  }
};

const clickExact = async (page, text) => {
  const btn = dropdown(page).locator("button").filter({ hasText: new RegExp(`^\\s*${text.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\\s*$`) }).first();
  await btn.click();
};

const pickerRows = async (page) => (await dropdown(page).locator("button").allInnerTexts()).map((t) => t.trim()).filter((t) => t.includes(" / "));

// Relation triplets from Global settings props (the store getDiscourseRelations reads).
const globalRelations = (page) =>
  page.evaluate(() => {
    const g = (o, k) => o?.[`:${k}`] ?? o?.[k];
    const cfg = window.roamAlphaAPI.pull("[{:block/children [:block/uid :block/string :block/props]}]", [":node/title", "roam/js/discourse-graph"]);
    const gb = (cfg?.[":block/children"] || []).find((c) => c[":block/string"] === "Global");
    return Object.entries(g(gb?.[":block/props"], "Relations") || {}).map(([id, r]) => ({ id: id.replace(/^:/, ""), label: g(r, "label"), complement: g(r, "complement"), source: g(r, "source"), destination: g(r, "destination") }));
  });

const grammarBlocks = (page) =>
  page.evaluate(() => {
    const cfg = window.roamAlphaAPI.pull("[{:block/children [:block/uid :block/string {:block/children ...}]}]", [":node/title", "roam/js/discourse-graph"]);
    const grammar = (cfg?.[":block/children"] || []).find((c) => /^grammar$/i.test(c[":block/string"]));
    const rel = (grammar?.[":block/children"] || []).find((c) => /^relations$/i.test(c[":block/string"]));
    const val = (b, k) => (b[":block/children"] || []).find((c) => new RegExp(`^${k}$`, "i").test(c[":block/string"]))?.[":block/children"]?.[0]?.[":block/string"];
    return { relationsUid: rel?.[":block/uid"], blocks: (rel?.[":block/children"] || []).map((r) => ({ uid: r[":block/uid"], label: r[":block/string"], source: val(r, "source"), destination: val(r, "destination"), complement: val(r, "complement") })) };
  });

const storedRelations = (page, uids) =>
  page.evaluate(async (uids) => {
    const rows = await window.roamAlphaAPI.data.async.q(`[:find ?u ?d :where [?s :block/uid ?u] [?s :block/props ?p] [(get ?p :discourse-graph) ?d]]`);
    const g = (o, k) => o?.[`:${k}`] ?? o?.[k];
    return rows
      .map(([u, d]) => ({ uid: u, sourceUid: g(d, "sourceUid"), destinationUid: g(d, "destinationUid"), hasSchema: g(d, "hasSchema") }))
      .filter((r) => uids.includes(r.sourceUid) || uids.includes(r.destinationUid));
  }, uids);

// Mirrors createRelationSchema: grammar block + Global.Relations entry.
const createTriplet = (page, t) =>
  page.evaluate(async ({ label, complement, source, destination, ifFrom }) => {
    const cfg = window.roamAlphaAPI.pull("[{:block/children [:block/uid :block/string {:block/children [:block/uid :block/string]}]}]", [":node/title", "roam/js/discourse-graph"]);
    const grammar = (cfg?.[":block/children"] || []).find((c) => /^grammar$/i.test(c[":block/string"]));
    const rel = (grammar?.[":block/children"] || []).find((c) => /^relations$/i.test(c[":block/string"]));
    const gb = (cfg?.[":block/children"] || []).find((c) => c[":block/string"] === "Global");
    const uid = window.roamAlphaAPI.util.generateUID();
    const api = window.roamAlphaAPI.data.block;
    await api.create({ location: { "parent-uid": rel[":block/uid"], order: "last" }, block: { uid, string: label } });
    for (const [i, [k, v]] of [["source", source], ["destination", destination], ["complement", complement]].entries()) {
      const cu = window.roamAlphaAPI.util.generateUID();
      await api.create({ location: { "parent-uid": uid, order: i }, block: { uid: cu, string: k } });
      await api.create({ location: { "parent-uid": cu, order: 0 }, block: { string: v } });
    }
    const norm = (p) => (p && typeof p === "object" && !Array.isArray(p) ? Object.fromEntries(Object.entries(p).map(([k, v]) => [k.replace(/^:+/, ""), norm(v)])) : Array.isArray(p) ? p.map(norm) : p);
    const raw = window.roamAlphaAPI.pull("[:block/props]", [":block/uid", gb[":block/uid"]])?.[":block/props"] || {};
    const props = norm(raw);
    const ifConditions = ifFrom ? JSON.parse(JSON.stringify(props.Relations?.[ifFrom]?.ifConditions || [])) : [];
    props.Relations = { ...(props.Relations || {}), [uid]: { label, source, destination, complement, ifConditions } };
    await api.update({ block: { uid: gb[":block/uid"], props } });
    return uid;
  }, t);

// Mirrors deleteRelationSchema for every triplet whose complement carries the marker.
const deleteMarkedTriplets = (page) =>
  page.evaluate(async (mark) => {
    const g = (o, k) => o?.[`:${k}`] ?? o?.[k];
    const cfg = window.roamAlphaAPI.pull("[{:block/children [:block/uid :block/string :block/props {:block/children ...}]}]", [":node/title", "roam/js/discourse-graph"]);
    const grammar = (cfg?.[":block/children"] || []).find((c) => /^grammar$/i.test(c[":block/string"]));
    const rel = (grammar?.[":block/children"] || []).find((c) => /^relations$/i.test(c[":block/string"]));
    const val = (b, k) => (b[":block/children"] || []).find((c) => new RegExp(`^${k}$`, "i").test(c[":block/string"]))?.[":block/children"]?.[0]?.[":block/string"];
    const blocks = (rel?.[":block/children"] || []).filter((r) => (val(r, "complement") || "").includes(mark) || (r[":block/string"] || "").includes(mark));
    const deletedBlocks = [];
    for (const b of blocks) { await window.roamAlphaAPI.data.block.delete({ block: { uid: b[":block/uid"] } }); deletedBlocks.push(`${b[":block/uid"]}|${b[":block/string"]}|${val(b, "complement")}`); }
    const gb = (cfg?.[":block/children"] || []).find((c) => c[":block/string"] === "Global");
    const norm = (p) => (p && typeof p === "object" && !Array.isArray(p) ? Object.fromEntries(Object.entries(p).map(([k, v]) => [k.replace(/^:+/, ""), norm(v)])) : Array.isArray(p) ? p.map(norm) : p);
    const raw = window.roamAlphaAPI.pull("[:block/props]", [":block/uid", gb[":block/uid"]])?.[":block/props"] || {};
    const props = norm(raw);
    const deletedGlobal = [];
    for (const [id, r] of Object.entries(props.Relations || {})) {
      if ((r.complement || "").includes(mark) || (r.label || "").includes(mark)) { delete props.Relations[id]; deletedGlobal.push(`${id}|${r.label}|${r.complement}`); }
    }
    if (deletedGlobal.length) await window.roamAlphaAPI.data.block.update({ block: { uid: gb[":block/uid"], props } });
    return { deletedBlocks, deletedGlobal };
  }, MARK);

const recorder = (outDir) => {
  const out = {};
  const flush = () => fs.writeFileSync(`${outDir}/eng2244-result.json`, JSON.stringify(out, null, 2));
  const step = async (name, fn) => {
    try { out[name] = await fn(); } catch (e) { out[name] = { error: String(e?.message || e).slice(0, 600) }; }
    flush();
    return out[name];
  };
  return { out, step, flush };
};

const LX = `${MARK} backs`;
const CX = `${MARK} backed by`;
const LN = `${MARK} informs`;
const CN = `${MARK} informed by`;
const LN2 = `${MARK} extends`;
const CN2 = `${MARK} extended by`;

let enabledByTest = null;

const openSettings = async (page) => {
  await page.keyboard.press("Meta+p");
  await sleep(page, 700);
  await page.keyboard.type("DG: Open - Discourse settings");
  await sleep(page, 700);
  await page.keyboard.press("Enter");
  await sleep(page, 2000);
  return page.locator("label", { hasText: "Enable stored relations" }).first();
};

// Toggling opens a confirmation dialog; prefer the path that skips migration.
const setStoredRelations = async (page, outDir, on) => {
  const label = await openSettings(page);
  await label.locator("input").click({ force: true });
  await sleep(page, 1500);
  await page.screenshot({ path: `${outDir}/eng2244-stored-toggle-${on ? "on" : "off"}.png` });
  const choices = on ? ["Reactivate without Migration", "Activate and Migrate"] : ["Deactivate"];
  let clicked = null;
  for (const text of choices) {
    const btn = page.locator(".bp3-dialog button", { hasText: text }).first();
    if (await btn.count()) { await btn.click(); clicked = text; break; }
  }
  for (let i = 0; i < 120 && clicked === "Activate and Migrate"; i += 1) {
    if (!(await page.locator(".bp3-dialog", { hasText: "Migrating relations" }).count())) break;
    await sleep(page, 1000);
  }
  await sleep(page, 1500);
  const checked = await label.locator("input").isChecked().catch(() => null);
  await closeDialogs(page);
  return { clicked, checked };
};

const dialog = (page) => page.locator(".bp3-dialog").filter({ hasText: "Add relation type" }).first();
const dialogOpen = async (page) => (await dialog(page).count()) > 0 && (await dialog(page).isVisible());
const dialogError = async (page) => ((await dialog(page).locator(".text-red-700").count()) ? (await dialog(page).locator(".text-red-700").innerText()).trim() : null);
const fill = async (page, label, complement) => {
  await page.locator("#dg-new-relation-label").fill(label);
  await page.locator("#dg-new-relation-complement").fill(complement);
};
const continueBtn = (page) => dialog(page).locator("button", { hasText: "Continue" });
const toastTexts = (page) => page.locator(".tlui-toast__container").allInnerTexts().then((ts) => ts.map((t) => t.replace(/\s+/g, " ").trim())).catch(() => []);
const waitToast = (page, text) => page.locator(".tlui-toast__container").filter({ hasText: text }).first().waitFor({ state: "visible", timeout: 10000 });

export default {
  async ready({ page }) {
    await closeDialogs(page);
    return page.evaluate(() => Boolean(window.roamAlphaAPI && window.roamjs?.extension?.queryBuilder));
  },
  async run({ page, outDir }) {
    const logs = [];
    page.on("console", (m) => { if (["error", "warning"].includes(m.type())) logs.push(`[${m.type()}] ${m.text().slice(0, 250)}`); });
    page.on("pageerror", (e) => logs.push(`[pageerror] ${String(e?.message || e).slice(0, 250)}`));
    const { out, step } = recorder(outDir);
    out.shots = {};

    out.preexistingMarked = (await globalRelations(page)).filter((r) => `${r.label}${r.complement}`.includes(MARK)).length;
    if (out.preexistingMarked) throw new Error("marker already present in relations; refusing to run");

    out.storedRelationsSetting = await step("storedRelationsSetting", async () => {
      const label = await openSettings(page);
      const found = await label.count();
      const initial = found ? await label.locator("input").isChecked().catch(() => null) : null;
      await closeDialogs(page);
      if (initial !== false) return { found, initial, checked: initial };
      const toggled = await setStoredRelations(page, outDir, true);
      enabledByTest = toggled.checked === true;
      return { found, initial, ...toggled };
    });
    if (out.storedRelationsSetting?.checked !== true) throw new Error(`stored relations setting not ON: ${JSON.stringify(out.storedRelationsSetting)}`);

    // Fixtures: T0 on an unrelated pair (for validation), TX on Conclusion -> Consequence (pair with types).
    out.fixtures = await step("fixtures", async () => {
      const T0 = await createTriplet(page, { label: L0, complement: C0, source: NODE.result, destination: NODE.test });
      const TX = await createTriplet(page, { label: LX, complement: CX, source: NODE.conclusion, destination: NODE.consequence });
      const fmt = await page.evaluate(() => {
        const g = (o, k) => o?.[`:${k}`] ?? o?.[k];
        const cfg = window.roamAlphaAPI.pull("[{:block/children [:block/string :block/props]}]", [":node/title", "roam/js/discourse-graph"]);
        const gb = (cfg?.[":block/children"] || []).find((c) => c[":block/string"] === "Global");
        return g(gb?.[":block/props"], "Canvas page format");
      });
      const canvasTitle = (fmt && fmt.includes("*") ? fmt : "Canvas/*").replace("*", `${MARK} canvas ${TS}`);
      const titles = { canvas: canvasTitle, q: `${MARK} question ${TS}`, h: `${MARK} hypothesis ${TS}`, x: `${MARK} conclusion X ${TS}`, y: `${MARK} consequence Y ${TS}` };
      const uids = {};
      for (const [k, t] of Object.entries(titles)) {
        uids[k] = window_uid();
        await page.evaluate(({ t, u }) => window.roamAlphaAPI.data.page.create({ page: { title: t, uid: u } }), { t, u: uids[k] });
      }
      await sleep(page, 1500);
      return { T0, TX, titles, uids };
    });
    const F = out.fixtures;
    if (F.error) throw new Error(F.error);

    await step("openCanvas", async () => {
      await page.evaluate((u) => window.roamAlphaAPI.ui.mainWindow.openPage({ page: { uid: u } }), F.uids.canvas);
      await installEditorFinder(page);
      const start = Date.now();
      while (Date.now() - start < 60000) {
        if (await page.evaluate(() => Boolean(window.__e2244Ed?.())).catch(() => false)) break;
        await sleep(page, 300);
      }
      await closeDialogs(page);
      await page.evaluate((n) => {
        const ed = window.__e2244Ed();
        ed.createShapes([
          { id: "shape:q", type: "discourse-node", x: 0, y: 0, props: { uid: n.q.uid, title: n.q.title, nodeTypeId: n.q.type, w: 220, h: 90 } },
          { id: "shape:h", type: "discourse-node", x: 600, y: 0, props: { uid: n.h.uid, title: n.h.title, nodeTypeId: n.h.type, w: 220, h: 90 } },
          { id: "shape:x", type: "discourse-node", x: 0, y: 400, props: { uid: n.x.uid, title: n.x.title, nodeTypeId: n.x.type, w: 220, h: 90 } },
          { id: "shape:y", type: "discourse-node", x: 600, y: 400, props: { uid: n.y.uid, title: n.y.title, nodeTypeId: n.y.type, w: 220, h: 90 } },
        ]);
        ed.zoomToFit();
        const cam = ed.getCamera();
        ed.setCamera({ ...cam, y: cam.y - 140 / cam.z });
        return true;
      }, {
        q: { uid: F.uids.q, title: F.titles.q, type: NODE.question },
        h: { uid: F.uids.h, title: F.titles.h, type: NODE.hypothesis },
        x: { uid: F.uids.x, title: F.titles.x, type: NODE.conclusion },
        y: { uid: F.uids.y, title: F.titles.y, type: NODE.consequence },
      });
      await sleep(page, 1500);
      return page.evaluate(() => window.__e2244Ed().getCurrentPageShapes().map((s) => `${s.id}|${s.props?.nodeTypeId}`));
    });

    // A: empty pair -> Create new opens the dialog; typing does not trigger canvas shortcuts; clicks keep the menu.
    out.a = await step("a_dialogOpens", async () => {
      await dragHandle(page, "shape:q", "shape:h");
      const emptyState = await dropdownButtons(page);
      await clickExact(page, "Create new");
      await sleep(page, 600);
      const open = await dialogOpen(page);
      const text = (await dialog(page).innerText()).replace(/\s+/g, " ").trim();
      const toolBefore = await page.evaluate(() => window.__e2244Ed().getCurrentToolId());
      const shapesBefore = await page.evaluate(() => window.__e2244Ed().getCurrentPageShapes().length);
      await page.locator("#dg-new-relation-label").click();
      // d/r/a/t/e/x/v/h are tldraw tool shortcuts.
      await page.keyboard.type("draw rect text arrow vhex");
      await sleep(page, 300);
      const typed = await page.locator("#dg-new-relation-label").inputValue();
      const toolAfter = await page.evaluate(() => window.__e2244Ed().getCurrentToolId());
      const shapesAfter = await page.evaluate(() => window.__e2244Ed().getCurrentPageShapes().length);
      await dialog(page).locator(".bp3-dialog-body").click({ position: { x: 5, y: 5 } });
      await sleep(page, 300);
      out.shots.dialog = await page.screenshot({ path: `${outDir}/eng2244-dialog.png` }).then(() => `${outDir}/eng2244-dialog.png`);
      const menuAfterClicks = await dropdownVisible(page);
      return { emptyState, open, text, typed, toolBefore, toolAfter, shapesBefore, shapesAfter, menuAfterClicks,
        pass: Boolean(open && text.includes("Question → Hypothesis") && typed === "draw rect text arrow vhex" && toolAfter === toolBefore && shapesAfter === shapesBefore && menuAfterClicks && (await dialogOpen(page))) };
    });

    // B: validation errors, each keeps the dialog open and saves nothing.
    out.b = await step("b_validation", async () => {
      const before = (await globalRelations(page)).length;
      const cases = [
        ["", "x", "Label and complement are required."],
        [L0.toUpperCase(), ` ${C0} `, "already exists. Use Add existing"],
        [L0, "something else", `already exists with complement "${C0}"`],
        ["anything new", L0, "already exists as a relation. To add it the other way round"],
        ["anything new", C0, `is already the complement of "${L0}"`],
        [C0, "anything new", `is already the complement of "${L0}". To add it the other way round`],
      ];
      const results = [];
      for (const [l, c, expected] of cases) {
        await fill(page, l, c);
        await continueBtn(page).click();
        await sleep(page, 500);
        const err = await dialogError(page);
        results.push({ l, c, err, ok: Boolean(err?.includes(expected)) && (await dialogOpen(page)) });
      }
      out.shots.validation = `${outDir}/eng2244-validation.png`;
      await page.screenshot({ path: out.shots.validation });
      const after = (await globalRelations(page)).length;
      return { results, savedNothing: before === after, pass: results.every((r) => r.ok) && before === after };
    });

    // C: Escape closes only the dialog; the menu stays.
    out.c = await step("c_escape", async () => {
      await page.locator("#dg-new-relation-label").click();
      await page.keyboard.press("Escape");
      await sleep(page, 600);
      const dialogAfter = await dialogOpen(page);
      const menuAfter = await dropdownVisible(page);
      return { dialogAfter, menuAfter, pass: !dialogAfter && menuAfter };
    });

    // D: Case 2 end to end on the empty pair: create, toasts, listed without refresh, draw, stored relation.
    out.d = await step("d_createEmptyPair", async () => {
      await clickExact(page, "Create new");
      await sleep(page, 500);
      await fill(page, ` ${LN} `, CN);
      await page.locator("#dg-new-relation-complement").press("Enter");
      await waitToast(page, "Discourse relation added");
      await sleep(page, 600);
      const toasts = await toastTexts(page);
      out.shots.toasts = `${outDir}/eng2244-toasts.png`;
      await page.screenshot({ path: out.shots.toasts });
      const dialogClosed = !(await dialogOpen(page));
      const listAfter = await dropdownButtons(page);
      out.shots.listed = await shot(page, outDir, "eng2244-type-listed.png");
      const created = (await globalRelations(page)).filter((r) => r.label === LN && r.source === NODE.question && r.destination === NODE.hypothesis);
      const grammar = (await grammarBlocks(page)).blocks.filter((b) => b.label === LN && b.source === NODE.question && b.destination === NODE.hypothesis);
      const newId = created[0]?.id;
      let arrows = [];
      if (listAfter.includes(LN)) {
        await clickExact(page, LN);
        await sleep(page, 5000);
        arrows = await page.evaluate(() => window.__e2244Ed().getCurrentPageShapes().filter((s) => s.type !== "discourse-node").map((s) => ({ id: s.id, type: s.type, relationTypeId: s.props?.relationTypeId, color: s.props?.color })));
        await page.evaluate(() => { window.__e2244Ed().selectNone(); return true; });
        await sleep(page, 400);
        out.shots.arrow = await shot(page, outDir, "eng2244-arrow-drawn.png");
      }
      const stored = await storedRelations(page, [F.uids.q, F.uids.h]);
      const match = stored.filter((s) => s.hasSchema === newId && s.sourceUid === F.uids.q && s.destinationUid === F.uids.h);
      const hasCreated = toasts.some((t) => t.includes("Relation type created"));
      const hasAdded = toasts.some((t) => t.includes(`${LN} added for Question and Hypothesis`));
      return { toasts, dialogClosed, listAfter, created, grammar, arrows, stored, match,
        pass: Boolean(hasCreated && hasAdded && dialogClosed && listAfter.includes(LN) && created.length === 1 && created[0].complement === CN && grammar.length === 1 && arrows.some((a) => a.relationTypeId === newId) && match.length === 1) };
    });

    // E: pair with types via "+": a shown label is rejected, then a new type is created and listed with the old one.
    out.e = await step("e_createPairWithTypes", async () => {
      await dragHandle(page, "shape:x", "shape:y");
      const list = await dropdownButtons(page);
      await dropdown(page).locator("button[aria-label='Add relation type']").click();
      await sleep(page, 300);
      await clickExact(page, "Create new");
      await sleep(page, 500);
      const header = (await dialog(page).innerText()).replace(/\s+/g, " ").trim();
      await fill(page, LX, "whatever");
      await continueBtn(page).click();
      await sleep(page, 500);
      const shownErr = await dialogError(page);
      await fill(page, LN2, CN2);
      await continueBtn(page).click();
      await waitToast(page, `${LN2} added for Conclusion and Consequence`);
      await sleep(page, 600);
      const listAfter = await dropdownButtons(page);
      out.shots.pairWithTypes = await shot(page, outDir, "eng2244-pair-with-types.png");
      const created = (await globalRelations(page)).filter((r) => r.label === LN2 && r.source === NODE.conclusion && r.destination === NODE.consequence);
      await page.keyboard.press("Escape"); await sleep(page, 300);
      await page.keyboard.press("Escape"); await sleep(page, 300);
      return { list, header, shownErr, listAfter, created,
        pass: Boolean(header.includes("Conclusion → Consequence") && shownErr?.includes(`"${LX}" is already a relation between these node types.`) && listAfter.includes(LX) && listAfter.includes(LN2) && created.length === 1) };
    });

    out.errors = logs.filter((l) => !/create-space|Could not log in|ERR_CONNECTION_REFUSED|Failed to create space/.test(l)).slice(0, 30);
    fs.writeFileSync(`${outDir}/eng2244-result.json`, JSON.stringify(out, null, 2));
    return { a: out.a?.pass, b: out.b?.pass, c: out.c?.pass, d: out.d?.pass, e: out.e?.pass, errors: out.errors.length, result: `${outDir}/eng2244-result.json` };
  },
  async cleanup({ page, outDir }) {
    const res = {};
    res.enabledByTest = enabledByTest;
    await page.keyboard.press("Escape").catch(() => {});
    // Leave the canvas so its unmount cannot rewrite the page after deletion.
    await page.evaluate(() => window.roamAlphaAPI.ui.mainWindow.openPage({ page: { title: "roam/js/discourse-graph" } })).catch(() => {});
    await sleep(page, 1500);
    const pages = await page.evaluate((mark) => window.roamAlphaAPI.q(`[:find ?u ?t :where [?p :node/title ?t] [?p :block/uid ?u] [(clojure.string/includes? ?t "${mark}")]]`), MARK);
    const nodeUids = pages.map(([u]) => u);
    const stored = await storedRelations(page, nodeUids);
    for (const s of stored) await page.evaluate((u) => window.roamAlphaAPI.data.block.delete({ block: { uid: u } }), s.uid);
    res.deletedStoredRelations = stored.map((s) => `${s.uid}|${s.hasSchema}|${s.sourceUid}->${s.destinationUid}`);
    res.triplets = await deleteMarkedTriplets(page);
    for (const [u] of pages) await page.evaluate((u) => window.roamAlphaAPI.data.page.delete({ page: { uid: u } }), u);
    res.deletedPages = pages.map(([u, t]) => `${u}|${t}`);
    await sleep(page, 1500);
    // Blocks the legacy save path wrote onto pages we did not create (they reference our node titles).
    const strays = await page.evaluate((mark) => window.roamAlphaAPI.q(`[:find ?u ?s :where [?b :block/string ?s] [?b :block/uid ?u] [(clojure.string/includes? ?s "${mark}")]]`), MARK);
    for (const [u] of strays) await page.evaluate((u) => window.roamAlphaAPI.data.block.delete({ block: { uid: u } }), u);
    res.deletedStrayBlocks = strays.map(([u, s]) => `${u}|${s.slice(0, 120)}`);
    await sleep(page, 2500);
    res.remaining = {
      pages: await page.evaluate((mark) => window.roamAlphaAPI.q(`[:find (count ?p) . :where [?p :node/title ?t] [(clojure.string/includes? ?t "${mark}")]]`), MARK),
      blocks: await page.evaluate((mark) => window.roamAlphaAPI.q(`[:find (count ?b) . :where [?b :block/string ?s] [(clojure.string/includes? ?s "${mark}")]]`), MARK),
      globalRelations: (await globalRelations(page)).filter((r) => `${r.label}${r.complement}`.includes(MARK)).length,
      storedRelations: (await storedRelations(page, nodeUids)).length,
    };
    if (enabledByTest) res.storedRelationsRestore = await setStoredRelations(page, outDir, false).catch((e) => ({ error: String(e?.message || e) }));
    fs.writeFileSync(`${outDir}/eng2244-cleanup.json`, JSON.stringify(res, null, 2));
    return res;
  },
};
function window_uid() {
  const chars = "REDACTED";
  return Array.from({ length: 9 }, () => chars[Math.floor(Math.random() * chars.length)]).join("");
}
async function deleteTripletById(page, id) {
  await page.evaluate(async (id) => {
    await window.roamAlphaAPI.data.block.delete({ block: { uid: id } });
    const cfg = window.roamAlphaAPI.pull("[{:block/children [:block/uid :block/string]}]", [":node/title", "roam/js/discourse-graph"]);
    const gb = (cfg?.[":block/children"] || []).find((c) => c[":block/string"] === "Global");
    const norm = (p) => (p && typeof p === "object" && !Array.isArray(p) ? Object.fromEntries(Object.entries(p).map(([k, v]) => [k.replace(/^:+/, ""), norm(v)])) : Array.isArray(p) ? p.map(norm) : p);
    const props = norm(window.roamAlphaAPI.pull("[:block/props]", [":block/uid", gb[":block/uid"]])?.[":block/props"] || {});
    delete props.Relations[id];
    await window.roamAlphaAPI.data.block.update({ block: { uid: gb[":block/uid"], props } });
  }, id);
  await page.waitForTimeout(300);
}

